<script setup lang="ts">
import {can} from './session'
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('ListingPanel')

const props=defineProps<{initialStore?:string}>()
import {ref,reactive,computed,onMounted,onBeforeUnmount,onActivated} from 'vue'
import {ElMessage} from 'element-plus'
import {Search,Refresh,ArrowLeft,Box,InfoFilled} from '@element-plus/icons-vue'
import {pendingPrice,trackPriceJobs} from './priceJobs'
import ListingSyncDialog from './ListingSyncDialog.vue'
const syncListingOpen=ref(false)
import ListingValue from './ListingValue.vue'
import ListingLog from './ListingLog.vue'
const logRow=ref<Listing|null>(null)
import ListingEditorField from './ListingEditorField.vue'
import ListingSubmitPreview from './ListingSubmitPreview.vue'
import ListingEditorRead from './ListingEditorRead.vue'
import CopyValue from './CopyValue.vue'
import ListingProductDialog from './ListingProductDialog.vue'
import ListingIncomeDialog from './ListingIncomeDialog.vue'
import ListingPriceDialog from './ListingPriceDialog.vue'
import ListingArrivalDialog from './ListingArrivalDialog.vue'
import type {Listing,ListingDetail,SubmitPreview,Submission} from './listingTypes'
const tableVersion=ref(0)
const columnWidths=computed(()=>tableWidths.tables['table-1']||{})
function resizeColumn(width:number,_old:number,column:{columnKey:string}){tableWidths.resize('table-1',width,column)}

const incomeRow=ref<Listing|null>(null),incomeResults=ref<Record<number,any>>({})
const linkRow=ref<Listing|null>(null)
const priceRow=ref<Listing|null>(null),arrivalRow=ref<Listing|null>(null),stockBusy=ref(false),arrivalBusy=ref(false),priceEditing=ref(false),priceBusy=ref(false)
let arrivalPoll:ReturnType<typeof setTimeout>|undefined
const rows=ref<Listing[]>([]),types=ref<string[]>([]),stores=ref<string[]>([]),markets=ref<string[]>([]),sampleCount=ref(0),total=ref(0),loading=ref(false),busy=ref(false),error=ref(''),selected=ref<ListingDetail|null>(null),section=ref('content'),preview=ref<SubmitPreview|null>(null)
const filters=reactive({q:'',store:props.initialStore||'',marketplace:'',sort_period:'today',sort_order:'desc',page:1,page_size:20}),form=ref<Record<string,any[]>>({}),baseline=ref<Record<string,any[]>>({})
const checking=ref(false),previewError=ref('')
let previewGeneration=0
const edits=new Map<number,{data:ListingDetail,form:Record<string,any[]>,base:Record<string,any[]>}>()
const typeNames:Record<string,string>={DISHWARE_PLACE_SETTING:'餐具套装',WATER_FLOTATION_DEVICE:'水上漂浮用品',COSTUME_HEADWEAR:'装扮帽饰',FOOD_STORAGE_BAG:'食品储存袋',SNOW_GLOBE:'雪景装饰品'}
const marketNames:Record<string,string>={UK:'英国',DE:'德国',FR:'法国',IT:'意大利',ES:'西班牙',BE:'比利时',NL:'荷兰',PL:'波兰',SE:'瑞典',IE:'爱尔兰'}
const time=(s:string|null)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚未获取'
const clone=<T,>(x:T):T=>JSON.parse(JSON.stringify(x))
const changes=computed(()=>Object.fromEntries((selected.value?.edit_fields||[]).filter(f=>f.editable&&JSON.stringify(form.value[f.key])!==JSON.stringify(baseline.value[f.key])).map(f=>[f.key,form.value[f.key]])))
const dirty=computed(()=>!!Object.keys(changes.value).length)
const arrivalRunning=computed(()=>arrivalBusy.value||rows.value.some(r=>['queued','running'].includes(r.arrivals.status)))
const otherGroups=computed(()=>(selected.value?.groups||[]).filter(g=>!['shipping','safety_and_compliance'].includes(g.key)).map(g=>({...g,fields:g.fields.filter(f=>!selected.value!.edit_fields.some(e=>e.key===f.key))})).filter(g=>g.fields.length))
const catalogSummary=computed(()=>selected.value?.catalog_data?.summaries?.[0])
const images=computed(()=>{const all=selected.value?.catalog_data?.images?.flatMap(g=>g.images)||[];const seen=new Set<string>();return all.filter(i=>{if(!i.link?.startsWith('https://')||seen.has(i.variant))return false;seen.add(i.variant);return true}).slice(0,9)})
async function api(path:string,body?:unknown){const response=await fetch('/api/listings'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-ERP-Client':'web'},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(response.status===401)window.dispatchEvent(new Event('erp:unauthorized'));if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'操作失败，请检查输入');return data}
const salesText=(r:Listing,k:string)=>`${r.sales.values[k]?.units??'—'}${r.sales.values[k]?.complete?'':'*'}`
const priceText=(v:string|null)=>v===null?'—':Number(v).toFixed(2)
const saleText=(r:Listing)=>r.pricing.sale_status==='expired'?'—':priceText(r.pricing.sale_price)
function stockTip(r:Listing){const x=r.inventory;return `${x.error||''} 可售 ${x.available??'未获取'}；接收中 ${x.receiving??'未获取'}；入库中（仓内处理中，可能含测量、检查）${x.processing??'未获取'}；已发货未接收（可能含已送达待接收）${x.shipped??'未获取'}；计划未发货 ${x.working??'未获取'}（不计在途）。读取时间：${time(x.synced_at)}`}
async function syncArrivals(){arrivalBusy.value=true;try{await api('/arrivals/refresh',{});await load();ElMessage.success('预计到达信息已开始后台同步，可继续使用页面')}catch(e){ElMessage.error((e as Error).message)}finally{arrivalBusy.value=false}}
function pollArrivals(){if(arrivalPoll)clearTimeout(arrivalPoll);if(!disposed&&rows.value.some(r=>['queued','running'].includes(r.arrivals.status)))arrivalPoll=setTimeout(()=>load(true),4000)}
async function syncStock(){stockBusy.value=true;try{const d=await api('/inventory/refresh',{});await load();if(d.failed)ElMessage.warning(`库存读取完成：${d.succeeded} 个成功，${d.failed} 个未成功，已保留旧值`);else ElMessage.success(`已读取 ${d.succeeded} 个商品库存`)}catch(e){ElMessage.error((e as Error).message)}finally{stockBusy.value=false}}

let listingRequest=0,inFlight=0,disposed=false,appliedQuery=''
async function load(silent=false){
 if(disposed)return
 if(silent&&(inFlight>0||loading.value||selected.value||document.hidden)){pollArrivals();return}
 if(arrivalPoll)clearTimeout(arrivalPoll)
 const request=++listingRequest
 if(!silent){filters.q=filters.q.replace(/^[\s\u200B\uFEFF]+|[\s\u200B\uFEFF]+$/g,'');appliedQuery=new URLSearchParams(Object.fromEntries(Object.entries(filters).map(([k,v])=>[k,String(v??'')]))).toString();loading.value=true}
 inFlight++
 try{
  const data=await api('?'+appliedQuery);if(disposed||request!==listingRequest)return
  const old=new Map(rows.value.map(r=>[r.id,r]))
  const next=data.listings.map((r:Listing)=>{const previous=old.get(r.id);return previous&&JSON.stringify(previous)===JSON.stringify(r)?previous:r})
  if(next.length!==rows.value.length||next.some((r:Listing,i:number)=>r!==rows.value[i]))rows.value=next
  trackPriceJobs(rows.value);if(!silent)incomeResults.value={}
  types.value=data.product_types;stores.value=data.stores;markets.value=data.markets;sampleCount.value=data.sample_count;total.value=data.total;error.value=''
 }catch(e){if(!silent&&!disposed&&request===listingRequest)error.value=(e as Error).message}
 finally{inFlight--;if(request===listingRequest){if(!silent)loading.value=false;pollArrivals()}}
}
function search(){filters.page=1;load()}
function hydrate(data:ListingDetail){selected.value=data;baseline.value=Object.fromEntries(data.edit_fields.map(f=>[f.key,clone(f.value)]));form.value=clone(baseline.value)}
function stash(){if(!selected.value)return;if(dirty.value)edits.set(selected.value.id,{data:clone(selected.value),form:clone(form.value),base:clone(baseline.value)});else edits.delete(selected.value.id)}
async function open(row:Listing){loading.value=true;try{const saved=edits.get(row.id);if(saved){selected.value=clone(saved.data);form.value=clone(saved.form);baseline.value=clone(saved.base)}else hydrate(await api('/'+row.id));section.value='content';error.value=''}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}
async function canLeave(){if(busy.value||priceBusy.value){ElMessage.info('当前操作尚未结束，请稍候');return false}if(preview.value||priceRow.value||linkRow.value||incomeRow.value){ElMessage.info('请先关闭提交预览或调价窗口');return false}stash();return true}
defineExpose({canLeave})
async function back(){if(await canLeave()){selected.value=null;load()}}
async function refreshDetail(){if(!selected.value)return;const pending=clone(changes.value);busy.value=true;try{hydrate(await api('/'+selected.value.id+'/refresh',{}));for(const [key,v] of Object.entries(pending))form.value[key]=v;ElMessage.success(Object.keys(pending).length?'最新信息已读取，前端编辑已保留；请在提交预览核对差异':'最新信息已读取')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
function closePreview(){previewGeneration++;preview.value=null;checking.value=false;previewError.value='';busy.value=false}
async function showPreview(){
 if(!selected.value||!dirty.value)return
 const generation=++previewGeneration,d=selected.value,pending=clone(changes.value)
 previewError.value='';checking.value=true;busy.value=true
 preview.value={preview_id:null,can_submit:false,expires_at:'',store:d.store,marketplace:d.marketplace,sku:d.sku,counts:{},warnings:[],issues:[],diff:Object.entries(pending).map(([key,value])=>{const f=d.edit_fields.find(f=>f.key===key)!;return {key,label:f.label,before:clone(baseline.value[key]),after:value,schema:f.schema}})}
 try{const result=await api('/'+d.id+'/preview',{expected_version:d.version,changes:pending});if(generation===previewGeneration)preview.value=result}
 catch(e){if(generation===previewGeneration)previewError.value=(e as Error).message}
 finally{if(generation===previewGeneration){checking.value=false;busy.value=false}}
}

async function submitted(result:Submission){if(!selected.value)return;selected.value.submissions=[result,...selected.value.submissions.filter(s=>s.id!==result.id)];if(['accepted','verified'].includes(result.status)){try{const data=await api('/'+selected.value.id);edits.delete(selected.value.id);hydrate(data);await load()}catch(e){ElMessage.warning('提交已记录，但页面刷新失败；请到提交记录核对。')}}}
async function verify(s:Submission){if(!selected.value)return;busy.value=true;try{const result=await api(`/${selected.value.id}/submissions/${s.id}/verify`,{});selected.value.submissions=selected.value.submissions.map(x=>x.id===result.id?result:x);ElMessage.info(result.message)}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
function legacy(){if(!selected.value?.draft)return;for(const [k,v] of Object.entries(selected.value.draft.changes)){if(selected.value.edit_fields.some(f=>f.key===k&&f.editable))form.value[k]=clone(v as any[])}ElMessage.info('旧版内容已载入前端，请预览后再决定提交')}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value||edits.size||busy.value||priceEditing.value||priceBusy.value){e.preventDefault();e.returnValue=''}}
onActivated(()=>{if(props.initialStore&&filters.store!==props.initialStore){filters.store=props.initialStore;filters.page=1;load()}})
function priceFinished(event:Event){const d=(event as CustomEvent).detail;for(const r of [...rows.value,...(selected.value?[selected.value]:[])]){if(r.id!==d.pk)continue;if(r.pending_price?.id===d.id)r.pending_price=null;if(d.pricing)r.pricing={...r.pricing,...d.pricing}}}
onMounted(()=>{window.addEventListener('erp:price-finished',priceFinished);load();window.addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>{disposed=true;listingRequest++;window.removeEventListener('erp:price-finished',priceFinished);window.removeEventListener('beforeunload',beforeUnload);if(arrivalPoll)clearTimeout(arrivalPoll)})
</script>
<template>
 <ListingIncomeDialog :row="incomeRow" @close="incomeRow=null" @calculated="d=>incomeResults[d.listing_id]=d"/>
 <ListingProductDialog :row="linkRow" @close="linkRow=null" @saved="load()"/>
 <ListingArrivalDialog :row="arrivalRow" @close="arrivalRow=null"/>
 <ListingPriceDialog :row="priceRow" @close="priceRow=null" @saved="load()" @editing="v=>priceEditing=v" @busy="v=>priceBusy=v"/>
 <ListingSubmitPreview :preview="preview" :checking="checking" :validation-error="previewError" :listing-id="selected?.id||0" @close="closePreview" @submitted="submitted" @busy="v=>busy=v"/>
 <el-alert v-if="error" :title="error" type="error" class="error-alert" :closable="false"/>
 <template v-if="!selected">
 
 <div class="listing-stats"><span>已导入 <b>{{sampleCount}}</b> 个 Listing</span><span>产品类型 <b>{{types.length}}</b> 种</span><span>当前筛选 <b>{{total}}</b> 个</span></div>
 <section class="panel"><form class="filters listing-filters" @submit.prevent="search"><el-input v-model="filters.q" class="keyword" placeholder="搜索 SKU / ASIN / 标题 / 品名" clearable :prefix-icon="Search"/><el-select v-model="filters.store" :value-on-clear="''" aria-label="店铺筛选" placeholder="全部店铺" clearable style="width:150px" @change="search"><el-option v-for="store in stores" :key="store" :value="store" :label="store"/></el-select><el-select v-model="filters.marketplace" :value-on-clear="''" aria-label="站点筛选" placeholder="全部站点" clearable style="width:130px" @change="search"><el-option v-for="market in markets" :key="market" :value="market" :label="`${marketNames[market]||market} · ${market}`"/></el-select><el-select v-model="filters.sort_period" aria-label="排序指标" style="width:145px" @change="search"><el-option v-for="(label,k) in {today:'今日销量',yesterday:'昨日销量','7':'7天销量','14':'14天销量','30':'30天销量',fba_available:'FBA可售库存'}" :key="k" :value="k" :label="label"/></el-select><el-select v-model="filters.sort_order" aria-label="排序方向" style="width:100px" @change="search"><el-option value="desc" label="降序"/><el-option value="asc" label="升序"/></el-select><el-button type="primary" native-type="submit">查询</el-button><el-button @click="Object.assign(filters,{q:'',store:props.initialStore||'',marketplace:'',sort_period:'today',sort_order:'desc',page:1});load()">重置</el-button><el-button :icon="Refresh" @click="load()">刷新列表</el-button><TableReset table-key="ListingPanel/table-1"/></form>
 <template v-if="true"><el-table data-width-key="ListingPanel/table-1" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-1', column, event)" class="listing-table" border :key="tableVersion" :data="rows" @header-dragend="resizeColumn" v-loading="loading" row-key="id" @row-dblclick="open"><el-table-column column-key="product" label="商品" :width="columnWidths.product" min-width="310"><template #default="{row}"><div class="listing-product"><el-image :src="row.image_url" fit="contain" class="listing-thumb"><template #error><el-icon><Box/></el-icon></template></el-image><div class="listing-product-copy"><div class="identifier-line"><button class="order-link" :title="row.sku" @click="open(row)">{{row.sku}}</button><CopyValue label="SKU" :value="row.sku"/></div><div class="listing-title" :title="row.title">{{row.title}}</div><div class="identifier-line muted"><span>ASIN：{{row.asin||'未返回'}}</span><CopyValue label="ASIN" :value="row.asin"/><span>· {{row.brand||'品牌未返回'}}</span></div><div class="identifier-line muted fnsku-line"><span>FNSKU：{{row.fnsku||'未返回'}}</span><CopyValue label="FNSKU" :value="row.fnsku"/></div></div></div></template></el-table-column><el-table-column column-key="localName" label="品名" :width="columnWidths.localName||170" show-overflow-tooltip><template #default="{row}">{{row.local_product?.name||''}}</template></el-table-column><el-table-column column-key="store" label="店铺 / 站点" :width="columnWidths.store||105"><template #default="{row}">{{row.store}}<div class="cell-sub">{{marketNames[row.marketplace]||row.marketplace}} · {{row.marketplace}}</div></template></el-table-column><el-table-column column-key="pricing" label="售价｜促销价" :width="columnWidths.pricing||155"><template #default="{row}"><div v-if="pendingPrice(row)" class="pending-price" title="后台调价处理中；亚马逊受理成功后显示新价格。"><div>售价：<strong>调价中 {{priceText(pendingPrice(row)!.price)}}</strong></div><div>促销：<strong>{{pendingPrice(row)!.sale_price===null?(row.pricing.sale_price!==null?'取消中':'—'):'调价中 '+priceText(pendingPrice(row)!.sale_price)}}</strong></div></div><div v-else class="metric-values" :title="row.pricing.price_source==='accepted_submission'?'亚马逊已受理的提交价格，实际生效以亚马逊为准':row.pricing.price_source==='current_offer'?'亚马逊当前普通买家报价；未返回常规售价':'常规售价'">{{priceText(row.pricing.price)}} <i>｜</i> <el-tooltip :content="`促销：${row.pricing.sale_price||'无'}，${row.pricing.sale_start||'—'} 至 ${row.pricing.sale_end||'—'}；${row.pricing.sale_status==='expired'?'已过期':row.pricing.sale_status==='scheduled'?'尚未开始':row.pricing.sale_status==='active'?'生效中':'无生效促销'}`"><span>{{saleText(row)}}</span></el-tooltip></div><div class="price-row-actions"><span class="muted">{{row.pricing.currency||'未返回币种'}}</span><el-button type="primary" link v-if="can('listing','operate')" @click.stop="priceRow=row">调价</el-button></div></template></el-table-column>

 <el-table-column column-key="salesToday" :width="columnWidths.salesToday||80"><template #header><el-tooltip content="今日当地零点至最近同步时点的下单件数，排除取消订单"><span class="metric-heading">销量 <el-icon><InfoFilled/></el-icon></span></el-tooltip></template><template #default="{row}"><el-tooltip :content="`今日销量；${row.sales.timezone}；订单截至 ${time(row.sales.as_of)}`"><span class="metric-values">{{salesText(row,'today')}}</span></el-tooltip></template></el-table-column>
 <el-table-column column-key="salesPeriods" :width="columnWidths.salesPeriods||225"><template #header><el-tooltip content="昨天及截至昨天的近 7/14/30 个完整自然日；按站点当地日期，下单商品件数，排除取消订单，* 表示数据未补齐"><span class="metric-heading">昨天｜7｜14｜30天销量 <el-icon><InfoFilled/></el-icon></span></el-tooltip></template><template #default="{row}"><div class="metric-values"><template v-for="(key,i) in ['yesterday','7','14','30']" :key="key"><i v-if="i">｜</i>{{salesText(row,key)}}</template></div><div class="cell-sub" v-if="Object.values(row.sales.values).some((v:any)=>!v.complete)">历史数据待补齐</div></template></el-table-column>
 <el-table-column column-key="inventory" :width="columnWidths.inventory||280"><template #header><el-tooltip content="可售＝可配送库存；接收中＝亚马逊接收中；入库中＝仓内处理中（可能含测量、检查）；在途＝亚马逊已发货未接收口径，可能含已送达待接收。计划未发货不计在途。"><span class="metric-heading">FBA可售｜接收中｜入库中｜在途 <el-icon><InfoFilled/></el-icon></span></el-tooltip></template><template #default="{row}"><el-tooltip :content="stockTip(row)"><div class="metric-values">{{row.inventory.available??'—'}} <i>｜</i> {{row.inventory.receiving??'—'}} <i>｜</i> {{row.inventory.processing??'—'}} <i>｜</i> {{row.inventory.shipped??'—'}}</div></el-tooltip><div v-if="row.inventory.error||row.inventory.stale" class="cell-sub">{{row.inventory.error?'读取异常，旧值保留':row.inventory.synced_at?'库存待刷新':'尚未同步'}}</div></template></el-table-column>
 <el-table-column column-key="arrivals" :width="columnWidths.arrivals||205"><template #header><el-tooltip content="未来 15/30/60 天内累计预计到仓件数（含今天）；按当前站点计划的送达窗口结束日期统计。三个数字不能相加；* 表示有缺失或逾期数据。点击数字查看货件。"><span class="metric-heading">15天｜30天｜60天内到达 <el-icon><InfoFilled/></el-icon></span></el-tooltip></template><template #default="{row}"><button class="arrival-link metric-values" @click.stop="arrivalRow=row" :aria-label="`${row.sku} 预计到达明细`"><template v-for="(days,i) in ['15','30','60']" :key="days"><i v-if="i">｜</i>{{row.arrivals.values[days]??'—'}}</template><sup v-if="row.arrivals.partial">*</sup></button><div class="cell-sub arrival-note">{{['queued','running'].includes(row.arrivals.status)?'正在同步…':row.arrivals.error?'同步异常，请查看明细':row.arrivals.unknown+row.arrivals.unverified?`待核对 ${row.arrivals.unknown+row.arrivals.unverified} 件`:row.arrivals.overdue?`已逾期 ${row.arrivals.overdue} 件`:!row.arrivals.synced_at?'尚未同步':row.arrivals.stale?'到达数据待刷新':row.arrivals.later?`60天后 ${row.arrivals.later} 件`:'预计到仓 · 点击查看'}}</div></template></el-table-column>
 <el-table-column column-key="type" label="产品类型" :width="columnWidths.type||145"><template #default="{row}"><b>{{typeNames[row.product_type]||row.product_type}}</b><div class="cell-sub type-code">{{row.product_type}}</div><div class="cell-sub">{{row.attribute_count}} 个现有属性</div></template></el-table-column><el-table-column column-key="status" label="状态" :width="columnWidths.status||105"><template #default="{row}"><el-tag :type="row.statuses.includes('BUYABLE')?'success':'info'">{{row.statuses.includes('BUYABLE')?'可售':'未返回可售标记'}}</el-tag><div class="cell-sub">{{row.issue_count}} 项接口问题</div></template></el-table-column><el-table-column column-key="actions" label="操作" :width="Math.max(columnWidths.actions||225,225)" fixed="right"><template #default="{row}"><el-button type="primary" link @click.stop="open(row)">{{can('listing','operate')?'编辑':'查看'}}</el-button><el-button type="primary" link v-if="can('listing','operate')" @click.stop="linkRow=row">关联</el-button><el-button type="primary" link @click.stop="incomeRow=row">计算</el-button><el-button type="primary" link @click.stop="logRow=row">日志</el-button><div v-if="row.local_product" class="cell-sub" :title="row.local_product.code">{{row.local_product.code}}</div></template></el-table-column><template #empty><el-empty description="没有匹配的 Listing"/></template></el-table></template><div class="listing-pagination"><el-pagination v-model:current-page="filters.page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="load()"/></div></section>
 </template>
 <template v-else>
